 "content": "from math import isqrt

def transform(grid):
    h, w = len(grid), len(grid[0])
    # A t-by-t collection of t-by-t tiles separated by single blank rows/cols:
    # dimension = t*(t+1)-1.
    t = isqrt(h + 1)
    if t * (t + 1) - 1 != h or w != h:
        raise ValueError("expected a square tiled grid")
    step = t + 1

    # Read the repeated tile motif from the first tile containing 2s.
    motif = None
    for br in range(t):
        for bc in range(t):
            r0, c0 = br * step, bc * step
            tile = [grid[r0 + r][c0:c0 + t] for r in range(t)]
            if any(v == 2 for row in tile for v in row):
                motif = [row[:] for row in tile]
                break
        if motif is not None:
            break
    if motif is None:
        return [[0] * w for _ in range(h)]

    # Each 2 in the motif selects an output tile at its matrix coordinate;
    # mark the corresponding local cell in that copy with 8. All separators
    # and unselected tiles (including the solid-3 guide band) become zero.
    out = [[0] * w for _ in range(h)]
    for br in range(t):
        for bc in range(t):
            if motif[br][bc] != 2:
                continue
            r0, c0 = br * step, bc * step
            for r in range(t):
                for c in range(t):
                    out[r0 + r][c0 + c] = motif[r][c]
            out[r0 + br][c0 + bc] = 8
    return out
